SPEC.F2=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[T('How the work runs',{x:7.5,y:11.5,w:70,h:7,s:4.4,b:true,tight:true})]);
  var d=[['Phase 01','Discover','Immersion in the product, the market and the people who use it in the field.',0],
         ['Phase 02','Align','One plan, shared metrics and a scope both teams can defend.',0],
         ['Phase 03','Execute','The embedded senior pod ships in your rituals, with your definition of done.',1],
         ['Phase 04','Learn','Measure on real operations and feed the next season’s roadmap.',0]];
  d.forEach(function(c,i){var x=7.5+i*21.8,y=21,w=20.2,h=28.2;
    s.push(card(x,y,w,h,C.w,C.hair));
    if(c[3])s.push(R({x:x,y:y,w:w,h:.5,fill:C.lime}));
    s.push(T(c[0].toUpperCase(),{x:x+1.8,y:y+2.2,w:w-3.6,h:2.2,s:1.15,b:true,c:C.g600,cs:1.3}));
    s.push(T(c[1],{x:x+1.8,y:y+5,w:w-3.6,h:4,s:1.9,b:true,tight:true}));
    s.push(T(c[2],{x:x+1.8,y:y+9.5,w:w-3.6,h:14,s:1.4,c:C.g600,lh:1.35}));});
  return s;};

SPEC.F3=function(p){
  var s=[bg(C.w)].concat(chrome(p),[T('One recommendation, four hands',{x:7.5,y:11.5,w:70,h:7,s:3.9,b:true,tight:true})]);
  var lw=13,gap=.7,cw=(85-lw-gap*4)/4, x0=7.5+lw+gap;
  s.push(T('FIELD SIGNAL',{x:x0,y:19,w:cw,h:2,s:1.05,b:true,c:C.em7,cs:1}));
  s.push(T('DECISION',{x:x0+2*(cw+gap),y:19,w:cw,h:2,s:1.05,b:true,c:C.em7,cs:1}));
  s.push(T('ACTION',{x:x0+3.4*(cw+gap),y:19,w:cw,h:2,s:1.05,b:true,c:C.em7,cs:1,al:'right'}));
  s.push(R({x:x0,y:20.2,w:85-lw-gap,h:.18,fill:C.g300}));
  var lanes=[['Grower',[['Flags a problem from the cab, offline',0],['Waits',2],['Reviews the recommendation on WhatsApp',0],['Applies it and confirms in one tap',3]]],
             ['Agronomist',[['Notified',2],['Validates against the field history',0],['Signs off or adjusts the dose',0],['Audits the outcome',2]]],
             ['Platform',[['Syncs when signal returns',1],['Runs the agronomic model',1],["Delivers to the grower's channel",1],['Logs the applied action',1]]],
             ['Magoya pod',[['Instruments the event',2],['Tunes the model with agronomy',2],['Tests the channel with real users',2],['Reads adoption weekly',2]]]];
  lanes.forEach(function(ln,r){var y=22+r*6.6;
    s.push(T(ln[0].toUpperCase(),{x:7.5,y:y+1.6,w:lw-1,h:3,s:1.15,b:true,c:C.g600,cs:1}));
    ln[1].forEach(function(cell,ci){var cx=x0+ci*(cw+gap),kind=cell[1];
      s.push(R({x:cx,y:y,w:cw,h:6,fill:kind===1?C.g900:(kind===3?C.lime:C.w),
        line:kind===0?C.hair:(kind===2?C.g300:null),lw:.75,radius:.8}));
      s.push(T(cell[0],{x:cx+1,y:y+.9,w:cw-2,h:4.4,s:1.25,c:kind===1?C.cr50:(kind===2?C.g600:C.ink),
        b:kind===3,lh:1.28}));});});
  return s;};

SPEC.F4=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[T('What comes out of a discovery',{x:7.5,y:11.5,w:70,h:7,s:4.2,b:true,tight:true})]);
  var caps=['01 · Wireframes','02 · Clickable prototype','03 · Prioritised backlog'];
  for(var i=0;i<3;i++){var x=7.5+i*29.5,y=21,w=27,h=28.2;
    s.push(card(x,y,w,h,C.w,C.hair));
    s.push(R({x:x,y:y,w:w,h:2.4,fill:C.g100}));
    for(var k=0;k<3;k++)s.push(R({x:x+1.2+k*1.2,y:y+.9,w:.65,h:.65,fill:C.g300,radius:.32}));
    if(i===0){s.push(R({x:x+1.6,y:y+4,w:16,h:1.7,fill:C.g200,radius:.3}));
      s.push(R({x:x+1.6,y:y+6.6,w:w-3.2,h:5.4,fill:C.g100,radius:.3}));
      s.push(R({x:x+1.6,y:y+13,w:19,h:.9,fill:C.g200,radius:.3}));
      s.push(R({x:x+1.6,y:y+14.6,w:10,h:.9,fill:C.g200,radius:.3}));}
    else if(i===1){s.push(R({x:x+1.6,y:y+4,w:16,h:1.7,fill:C.g900,radius:.3}));
      s.push(R({x:x+1.6,y:y+6.6,w:(w-4)/2,h:5.4,fill:C.g100,radius:.3}));
      s.push(R({x:x+2.4+(w-4)/2,y:y+6.6,w:(w-4)/2,h:5.4,fill:C.lime,radius:.3}));
      s.push(R({x:x+1.6,y:y+13,w:19,h:.9,fill:C.g200,radius:.3}));}
    else{s.push(R({x:x+1.6,y:y+4,w:16,h:1.7,fill:C.g200,radius:.3}));
      [0,1,2,3,4].forEach(function(k){s.push(R({x:x+1.6,y:y+6.8+k*2,w:(k%2?18:w-3.2),h:.9,fill:C.g200,radius:.3}));});}
    s.push(T(caps[i],{x:x+1.6,y:y+h-3.4,w:w-3.2,h:2.4,s:1.15,b:true,c:C.g600,cs:1}));}
  return s;};

/* --- G · casos de éxito --- */;
